}

.preview-font-medium {
    font-size: 1rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Compact mode */
.preview-compact {
    padding: 0.6rem 1rem;
    line-height: 1.3;
}

/* ───── Toast ───── */
.toast-message {
    position: fixed;
    bottom: 1.5rem;
    right: 1.5rem;
    background: #198754;
    color: #fff;
    padding: 0.75rem 1.5rem;
    border-radius: 6px;
