{"file_text": "@page "/settings"
@rendermode InteractiveServer
@using sv_a722060fdb884c809455770955da2632.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h4 class="sidebar-title">Settings</h4>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                <span class="sidebar-icon">@section.Value.Icon</span>
                <span>@section.Value.Label</span>
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center p-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toast))
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "")">
                @_toast
            </div>
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@{
    RenderFragment RenderProfile() =>
        @<section class="settings-section">
            <h3>Profile</h3>
            <div class="avatar-area">
