@page "/settings"
@rendermode InteractiveServer
@using sv_a722060fdb884c809455770955da2632.Services
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <nav class="settings-sidebar">
        <h4 class="sidebar-title">Settings</h4>
        @foreach (var section in _sections)
        {
            <button class="sidebar-item @(ActiveSection == section.Key ? "active" : "")"
                    @onclick="() => ActiveSection = section.Key">
                <span class="sidebar-icon">@section.Value.Icon</span>
                <span>@section.Value.Label</span>
            </button>
        }
    </nav>

    <div class="settings-content">
        @if (_loading)
        {
            <div class="text-center p-5"><div class="spinner-border" role="status"></div></div>
        }
        else
        {
            @switch (ActiveSection)
            {
                case "profile":
                    @RenderProfile()
                    break;
                case "notifications":
                    @RenderNotifications()
                    break;
                case "security":
                    @RenderSecurity()
                    break;
                case "appearance":
                    @RenderAppearance()
                    break;
            }
        }

        @if (!string.IsNullOrEmpty(_toast))
        {
            <div class="toast-message @(_toastIsError ? "toast-error" : "")">
                @_toast
            </div>
        }
    </div>
</div>

@* ───── Profile Section ───── *@
@{
    RenderFragment RenderProfile() =>
        @<section class="settings-section">
            <h3>Profile</h3>
            <div class="avatar-area">
                <img src="@_profileDisplayName" alt="" class="avatar-preview"
                     onerror="this.style.display='none'" />
                @* Show the avatar using the actual URL *@
                <img src="@_profileAvatarUrl" alt="Avatar" class="avatar-preview"
                     onerror="this.style.display='none'" />
                <span class="avatar-url-label">@_profileAvatarUrl</span>
            </div>

            <div class="form-group">
                <label>Display Name</label>
                <input class="form-control" @bind="_profileDisplayName" />
            </div>
            <div class="form-group">
                <label>Email</label>
                <input class="form-control" type="email" @bind="_profileEmail" />
            </div>
            <div class="form-group">
                <label>Bio</label>
                <textarea class="form-control" rows="4" @bind="_profileBio"></textarea>
            </div>
            <div class="form-group">
                <label>Avatar URL</label>
                <input class="form-control" @bind="_profileAvatarUrl" />
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveProfile">Save Changes</button>
                <button class="btn btn-outline-secondary" @onclick="DiscardProfile">Discard Changes</button>
            </div>
        </section>;
}

@* ───── Notifications Section ───── *@
@{
    RenderFragment RenderNotifications() =>
        @<section class="settings-section">
            <h3>Notifications</h3>

            <div class="toggle-row">
                <label class="toggle-label">Email Notifications</label>
                <label class="switch">
                    <input type="checkbox" @bind="_notifEmail" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Push Notifications</label>
                <label class="switch">
                    <input type="checkbox" @bind="_notifPush" />
                    <span class="slider"></span>
                </label>
            </div>
            <div class="toggle-row">
                <label class="toggle-label">Weekly Digest</label>
                <label class="switch">
                    <input type="checkbox" @bind="_notifDigest" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="mt-4">Muted Channels</h5>
            <div class="channel-list">
                @foreach (var channel in _allChannels)
                {
                    var ch = channel;
                    <label class="channel-item">
                        <input type="checkbox" checked="@_mutedChannels.Contains(ch)"
                               @onchange="e => ToggleMutedChannel(ch, (bool)(e.Value ?? false))" />
                        <span>#@ch</span>
                    </label>
                }
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveNotifications">Save Preferences</button>
            </div>
        </section>;
}

@* ───── Security Section ───── *@
@{
    RenderFragment RenderSecurity() =>
        @<section class="settings-section">
            <h3>Security</h3>

            <div class="expandable-panel">
                <button class="panel-header" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
                    <span>Change Password</span>
                    <span class="caret">@(_passwordPanelOpen ? "▲" : "▼")</span>
                </button>
                @if (_passwordPanelOpen)
                {
                    <div class="panel-body">
                        <div class="form-group">
                            <label>Current Password</label>
                            <input class="form-control" type="password" @bind="_currentPassword" />
                        </div>
                        <div class="form-group">
                            <label>New Password</label>
                            <input class="form-control" type="password" @bind="_newPassword" />
                        </div>
                        <div class="form-group">
                            <label>Confirm Password</label>
                            <input class="form-control" type="password" @bind="_confirmPassword" />
                        </div>
                        <button class="btn btn-primary" @onclick="ChangePassword">Update Password</button>
                    </div>
                }
            </div>

            <div class="toggle-row mt-3">
                <div>
                    <label class="toggle-label">Two-Factor Authentication</label>
                    <span class="badge @(_twoFactorEnabled ? "bg-success" : "bg-secondary") ms-2">
                        @(_twoFactorEnabled ? "Enabled" : "Disabled")
                    </span>
                </div>
                <label class="switch">
                    <input type="checkbox" @bind="_twoFactorEnabled" />
                    <span class="slider"></span>
                </label>
            </div>

            @if (_lastPasswordChange.HasValue)
            {
                <p class="text-muted mt-2">Last password change: @_lastPasswordChange.Value.ToString("MMMM dd, yyyy")</p>
            }

            <h5 class="mt-4">Active Sessions</h5>
            <table class="table session-table">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in _sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@FormatLastActive(session.LastActive)</td>
                            <td>
                                @if (session.Id != _sessions.FirstOrDefault()?.Id)
                                {
                                    <button class="btn btn-sm btn-outline-danger"
                                            @onclick="() => PromptRevokeSession(session)">
                                        Revoke
                                    </button>
                                }
                                else
                                {
                                    <span class="badge bg-info">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>

            @if (_sessionToRevoke is not null)
            {
                <div class="modal-overlay" @onclick="() => _sessionToRevoke = null">
                    <div class="confirm-dialog" @onclick:stopPropagation="true">
                        <h5>Revoke Session?</h5>
                        <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in @_sessionToRevoke.Location?</p>
                        <div class="button-row">
                            <button class="btn btn-danger" @onclick="RevokeSession">Revoke</button>
                            <button class="btn btn-outline-secondary" @onclick="() => _sessionToRevoke = null">Cancel</button>
                        </div>
                    </div>
                </div>
            }
        </section>;
}

@* ───── Appearance Section ───── *@
@{
    RenderFragment RenderAppearance() =>
        @<section class="settings-section">
            <h3>Appearance</h3>

            <div class="form-group">
                <label class="fw-semibold">Theme</label>
                <div class="radio-group">
                    @foreach (var theme in new[] { "Light", "Dark", "System" })
                    {
                        var t = theme;
                        <label class="radio-item">
                            <input type="radio" name="theme" value="@t"
                                   checked="@(_appearanceTheme == t)"
                                   @onchange="() => _appearanceTheme = t" />
                            <span>@t</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="fw-semibold">Font Size</label>
                <div class="radio-group">
                    @foreach (var size in new[] { "Small", "Medium", "Large" })
                    {
                        var s = size;
                        <label class="radio-item">
                            <input type="radio" name="fontSize" value="@s"
                                   checked="@(_appearanceFontSize == s)"
                                   @onchange="() => _appearanceFontSize = s" />
                            <span>@s</span>
                        </label>
                    }
                </div>
            </div>

            <div class="form-group">
                <label class="fw-semibold">Language</label>
                <select class="form-select" @bind="_appearanceLanguage">
                    <option value="English">English</option>
                    <option value="Spanish">Spanish</option>
                    <option value="French">French</option>
                    <option value="German">German</option>
                    <option value="Japanese">Japanese</option>
                    <option value="Chinese">Chinese</option>
                </select>
            </div>

            <div class="toggle-row">
                <label class="toggle-label">Compact Mode</label>
                <label class="switch">
                    <input type="checkbox" @bind="_appearanceCompact" />
                    <span class="slider"></span>
                </label>
            </div>

            <h5 class="mt-4">Preview</h5>
            <div class="appearance-preview @GetPreviewClasses()">
                <div class="preview-header">Sample Header</div>
                <p>This is a preview of your appearance settings. The selected theme, font size, and compact mode are reflected here.</p>
                <button class="preview-btn">Sample Button</button>
            </div>

            <div class="button-row">
                <button class="btn btn-primary" @onclick="SaveAppearance">Save</button>
            </div>
        </section>;
}

@code {
    private record SectionInfo(string Label, string Icon);

    private readonly Dictionary<string, SectionInfo> _sections = new()
    {
        ["profile"] = new("Profile", "👤"),
        ["notifications"] = new("Notifications", "🔔"),
        ["security"] = new("Security", "🔒"),
        ["appearance"] = new("Appearance", "🎨"),
    };

    private string ActiveSection { get; set; } = "profile";
    private bool _loading = true;
    private string? _toast;
    private bool _toastIsError;
    private CancellationTokenSource? _toastCts;

    // Profile state
    private string _profileDisplayName = "";
    private string _profileEmail = "";
    private string _profileAvatarUrl = "";
    private string _profileBio = "";
    private UserProfile? _savedProfile;

    // Notifications state
    private bool _notifEmail;
    private bool _notifPush;
    private bool _notifDigest;
    private HashSet<string> _mutedChannels = [];
    private List<string> _allChannels = [];

    // Security state
    private bool _passwordPanelOpen;
    private string _currentPassword = "";
    private string _newPassword = "";
    private string _confirmPassword = "";
    private bool _twoFactorEnabled;
    private DateTime? _lastPasswordChange;
    private List<ActiveSession> _sessions = [];
    private ActiveSession? _sessionToRevoke;

    // Appearance state
    private string _appearanceTheme = "Light";
    private string _appearanceFontSize = "Medium";
    private string _appearanceLanguage = "English";
    private bool _appearanceCompact;

    protected override async Task OnInitializedAsync()
    {
        _allChannels = InMemorySettingsService.GetAllChannels();
        await LoadAllSettings();
        _loading = false;
    }

    private async Task LoadAllSettings()
    {
        var profile = await SettingsService.GetProfileAsync();
        _savedProfile = profile;
        ApplyProfile(profile);

        var notifs = await SettingsService.GetNotificationPrefsAsync();
        _notifEmail = notifs.EmailNotifications;
        _notifPush = notifs.PushNotifications;
        _notifDigest = notifs.WeeklyDigest;
        _mutedChannels = [.. notifs.MutedChannels];

        var security = await SettingsService.GetSecuritySettingsAsync();
        _twoFactorEnabled = security.TwoFactorEnabled;
        _lastPasswordChange = security.LastPasswordChange;
        _sessions = [.. security.Sessions];

        var appearance = await SettingsService.GetAppearanceAsync();
        _appearanceTheme = appearance.Theme;
        _appearanceFontSize = appearance.FontSize;
        _appearanceLanguage = appearance.Language;
        _appearanceCompact = appearance.CompactMode;
    }

    private void ApplyProfile(UserProfile profile)
    {
        _profileDisplayName = profile.DisplayName;
        _profileEmail = profile.Email;
        _profileAvatarUrl = profile.AvatarUrl;
        _profileBio = profile.Bio;
    }

    // ───── Profile ─────

    private async Task SaveProfile()
    {
        var profile = new UserProfile(_profileDisplayName, _profileEmail, _profileAvatarUrl, _profileBio);
        await SettingsService.SaveProfileAsync(profile);
        _savedProfile = profile;
        ShowToast("Profile saved successfully.");
    }

    private void DiscardProfile()
    {
        if (_savedProfile is not null)
            ApplyProfile(_savedProfile);
        ShowToast("Changes discarded.");
    }

    // ───── Notifications ─────

    private void ToggleMutedChannel(string channel, bool muted)
    {
        if (muted) _mutedChannels.Add(channel);
        else _mutedChannels.Remove(channel);
    }

    private async Task SaveNotifications()
    {
        var prefs = new NotificationPrefs(_notifEmail, _notifPush, _notifDigest, [.. _mutedChannels]);
        await SettingsService.SaveNotificationPrefsAsync(prefs);
        ShowToast("Notification preferences saved.");
    }

    // ───── Security ─────

    private async Task ChangePassword()
    {
        if (string.IsNullOrWhiteSpace(_newPassword))
        {
            ShowToast("New password cannot be empty.", isError: true);
            return;
        }
        if (_newPassword != _confirmPassword)
        {
            ShowToast("Passwords do not match.", isError: true);
            return;
        }
        await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
        _lastPasswordChange = DateTime.UtcNow;
        _currentPassword = "";
        _newPassword = "";
        _confirmPassword = "";
        _passwordPanelOpen = false;
        ShowToast("Password updated successfully.");
    }

    private void PromptRevokeSession(ActiveSession session) => _sessionToRevoke = session;

    private async Task RevokeSession()
    {
        if (_sessionToRevoke is null) return;
        await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
        _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
        _sessionToRevoke = null;
        ShowToast("Session revoked.");
    }

    // ───── Appearance ─────

    private string GetPreviewClasses()
    {
        var classes = $"preview-theme-{_appearanceTheme.ToLowerInvariant()}";
        classes += $" preview-font-{_appearanceFontSize.ToLowerInvariant()}";
        if (_appearanceCompact) classes += " preview-compact";
        return classes;
    }

    private async Task SaveAppearance()
    {
        var settings = new AppearanceSettings(_appearanceTheme, _appearanceFontSize, _appearanceLanguage, _appearanceCompact);
        await SettingsService.SaveAppearanceAsync(settings);
        ShowToast("Appearance settings saved.");
    }

    // ───── Toast ─────

    private void ShowToast(string message, bool isError = false)
    {
        _toastCts?.Cancel();
        _toast = message;
        _toastIsError = isError;
        _toastCts = new CancellationTokenSource();
        var token = _toastCts.Token;
        _ = Task.Run(async () =>
        {
            await Task.Delay(3000, token);
            if (!token.IsCancellationRequested)
            {
                await InvokeAsync(() => { _toast = null; StateHasChanged(); });
            }
        }, token);
    }

    private static string FormatLastActive(DateTime lastActive)
    {
        var diff = DateTime.UtcNow - lastActive;
        if (diff.TotalMinutes < 1) return "Just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes}m ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        return $"{(int)diff.TotalDays}d ago";
    }
}

